typedef unsigned int size_t;
typedef unsigned char *PointerMath;
typedef size_t MemSize;
typedef unsigned int MemFlags;

#define HEAP_OFTYPE_LINKS
#define HEAPMAGICID 0x7E07
#define heapassert(exp) ((void)0)

enum MemoryBlockTypes
{
	mbtFree      = 0x00000000,
	mbtUsed      = 0x00000001,
};

struct MemFlagDWord
{
	MemFlags magic  : 16;
	MemFlags heapid :  8;
	MemFlags flags  :  8;
};

class MemBlockInfo
{
	public:
	MemBlockInfo *prev;
	MemBlockInfo *next;
	MemBlockInfo *prevoftype;
	MemBlockInfo *nextoftype;
	MemSize size;
	MemFlagDWord flags;
	MemFlags blockid;
};

class Heap
{
	public:
	MemBlockInfo *fullhead;
	MemBlockInfo *fulltail;
	MemBlockInfo *usedhead;
	MemBlockInfo *usedtail;
	MemBlockInfo *freehead;
	MemBlockInfo *freetail;
	MemSize heapsize;
	void *heapstart;
	MemSize allocatedblocks;
	MemSize minalloc;
	MemSize minalign;
	MemSize lastalloc;
	MemFlags heapid;

	MemFlags GetHeapID( void ) const { return heapid; }
	MemBlockInfo *SplitBlock( MemBlockInfo *block, MemSize blocksize );
	MemSize HeaderSize( void ) const;
	void SetBlockSentry( MemBlockInfo *block );
};

__asm__(".equ HeaderSize__C4Heap, 0x002AB370");
__asm__(".equ SetBlockSentry__4HeapP12MemBlockInfo, 0x002AB678");

MemBlockInfo *Heap::SplitBlock( MemBlockInfo *block, MemSize blocksize )
{
	heapassert(blocksize > HeaderSize());
	heapassert(block->size > blocksize+HeaderSize());
	PointerMath oblock=(PointerMath) block;
	PointerMath nblock=oblock+blocksize;
	MemBlockInfo *newblock=(MemBlockInfo * ) nblock;
	newblock->size = block->size - blocksize;
	newblock->flags.magic = HEAPMAGICID;
	newblock->flags.heapid = GetHeapID();
	newblock->flags.flags = block->flags.flags;
	newblock->prev=block;
	newblock->blockid=0;
	#ifdef HEAP_OFTYPE_LINKS
	newblock->prevoftype=block;
	#endif
	newblock->next=block->next;
	#ifdef HEAP_OFTYPE_LINKS
	newblock->nextoftype=block->nextoftype;
	#endif
	#ifdef HEAP_DEBUG
		strcpy(newblock->name,block->name);
		newblock->lineno=block->lineno;
	#endif
	block->next=newblock;
	#ifdef HEAP_OFTYPE_LINKS
	block->nextoftype=newblock;
	#endif
	if ( newblock->next )
	{
		newblock->next->prev=newblock;
	}
	else
	{
		fulltail=newblock;
	}
	#ifdef HEAP_OFTYPE_LINKS
	if ( newblock->nextoftype )
	{
		newblock->nextoftype->prevoftype=newblock;
	}
	else
	{
		if ( newblock->flags.flags & mbtUsed )
		{
			usedtail=newblock;
		}
		else
		{
			freetail=newblock;
		}
	}
	#endif
	//block->size-=blocksize;
	block->size=blocksize-HeaderSize();
	block->flags.magic = HEAPMAGICID;
	block->flags.heapid = GetHeapID();
	SetBlockSentry(block);
	SetBlockSentry(newblock);
	return block;
}
